INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT159-S3-Q20$batch10$, 159, 3, 20, $batch10$Main Conclusion$batch10$, $batch10$Essayist: Since ancient times humans have relied on myths to try to explain our place in the cosmos. In this respect the claims of science are not different from stories about the gods of Homer. The question of the truth of science, as with myth, is merely the question of how well it helps us to cope with the human condition. So while science undoubtedly can count some successes, that it falls short of complete truth is amply demonstrated by the degree to which science is responsible for the breakdown of society’s key institutions.$batch10$, $batch10$Which one of the following most accurately states the main conclusion of the essayist’s argument?$batch10$, $batch10$C$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$Science is at least in part responsible for the breakdown of key institutions in society.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$Science is no more true than the myth of the gods of Homer.$batch10$, $batch10$Too Strong$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$Science is only partially true.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$Science is merely a myth.$batch10$, $batch10$Too Strong$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$Science, like stories about the gods of Homer, attempts to explain our place in the cosmos.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Evidence$batch10$, $batch10$Science, like myth, tries to explain our place in the cosmos. The truth of science, like that of myth, is just a question of how well it helps us cope with the human condition.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$Science falls short of complete truth.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Science is responsible for the breakdown of society's key institutions, which shows it doesn't help us cope well.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"So" introduces the conclusion in the last sentence. "While science undoubtedly can count some successes" is a concession, and the main claim is that science "falls short of complete truth." The breakdown of institutions is the evidence for that.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Science is only partially true.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the evidence used to show science falls short.$batch10$), ($batch10$B$batch10$, $batch10$The essayist compares science to myth in one respect, not in how true it is.$batch10$), ($batch10$C$batch10$, $batch10$Some successes, but short of complete truth, means only partially true.$batch10$), ($batch10$D$batch10$, $batch10$The essayist says science is like myth in one respect. Saying it is merely a myth goes further.$batch10$), ($batch10$E$batch10$, $batch10$This is the comparison in the first two sentences, which supports the conclusion.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT159-S3-Q20$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
